import { useUser } from './session';

export function CurrentUser() {
  const [user, setUser] = useUser();
  return (
    <p>
      Signed in as <strong data-testid="current-user">{user}</strong>{' '}
      <button type="button" data-testid="signout" onClick={() => setUser(undefined)}>
        Sign out
      </button>
    </p>
  );
}
import { asString, useSearchParam } from '../../url/useSearchParam';

// Who is signed in and which sheet is active. Both live in the URL (`user`, `sheet`), so any
// feature reads them directly and a browser refresh keeps them.
export const useUser = () => useSearchParam('user', asString);
export const useSheetId = () => useSearchParam('sheet', asString);
import { useState } from 'react';
import { useUser } from './session';

/** Sign in by typing a name; there is no password. */
export function SignIn() {
  const [, setUser] = useUser();
  const [name, setName] = useState('');
  const [error, setError] = useState(false);

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        const trimmed = name.trim();
        if (!trimmed) {
          setError(true);
          return;
        }
        setUser(trimmed);
      }}
    >
      <label>
        Name{' '}
        <input
          data-testid="signin-name"
          value={name}
          onChange={(e) => {
            setName(e.target.value);
            setError(false);
          }}
        />
      </label>{' '}
